///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_requestIdConf
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_requestIdConf = async function () {
    const sbmOptions = {
        id: "tx_fn_requestIdConf",
        method: "post",
        action: "/corp/register.do?method=requestIdConf",
        ref: "dma_requestIdConfReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf00007.tx_fn_requestIdConf" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.emailCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name scwin.requestIdConf
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.requestIdConf = async function () {
    /* sdd-asis-lifecycle:begin fn_requestIdConf — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chkData()) {
        return;
    }
    const SendForm = (document.SendForm || { elements: [] });
    $c.util.getComponent('dma_requestIdConfReq').set('encrypChrgEmail', $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    scwin.form_SendForm.action = "/corp/register.do?method=requestIdConf";
    scwin.form_SendForm.target = "_self";
    await scwin.tx_fn_requestIdConf();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkData = async function () {
    /* sdd-asis-lifecycle:begin fn_chkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const SendForm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "")) == 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").setValue("");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if ($c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "").length < 5) {
            await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgNm').getValue()) == 0) {
                await $c.win.alert("이름을 입력하십시오.");
                $c.util.getComponent("ipt_chrgNm").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue()) == 0) {
                    await $c.win.alert("이메일을 입력하십시오.");
                    $c.util.getComponent("ipt_encrypChrgEmail1").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue()) == 0) {
                        await $c.win.alert("이메일을 입력하십시오.");
                        $c.util.getComponent("ipt_encrypChrgEmail2").focus();
                        return false;
                    } else {
                        if (!$c.str.isEmail($c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypChrgEmail2').getValue())) {
                            await $c.win.alert("이메일이 올바르지 않습니다.");
                            $c.util.getComponent("ipt_encrypChrgEmail2").focus();
                            return false;
                        }
                    }
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk_chrg_nm
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.chk_chrg_nm = async function (fm) {
    /* sdd-asis-lifecycle:begin chk_chrg_nm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const len = $c.str.getByteLength($c.util.getComponent('ipt_chrgNm').getValue());
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        $c.util.getComponent("ipt_chrgNm").focus();
        return;
    }
    /* sdd-asis-lifecycle:end */
};
